-- Versioned catalog update; preserve later versions and administrative enablement.
ON CONFLICT (plugin_id, version) DO NOTHING;
UPDATE cadu_chat_plugin_versions old SET is_current=FALSE WHERE old.plugin_id IN ('market-radar', 'audience-map', 'investment-simulator', 'media-plan-audit', 'campaign-tracker', 'creative-concept', 'channel-copy', 'page-review', 'meeting-copilot', 'client-delivery') AND old.version='1.0.0' AND old.is_current AND NOT EXISTS (SELECT 1 FROM cadu_chat_plugin_versions newer WHERE newer.plugin_id=old.plugin_id AND newer.is_current AND newer.version > '1.1.0');
UPDATE cadu_chat_plugin_versions current SET is_current=TRUE WHERE current.plugin_id IN ('market-radar', 'audience-map', 'investment-simulator', 'media-plan-audit', 'campaign-tracker', 'creative-concept', 'channel-copy', 'page-review', 'meeting-copilot', 'client-delivery') AND current.version='1.1.0' AND NOT current.is_current AND NOT EXISTS (SELECT 1 FROM cadu_chat_plugin_versions newer WHERE newer.plugin_id=current.plugin_id AND newer.is_current AND newer.version > '1.1.0');
